/* ===== friends + chat (readable legacy classes) ===== */
.friendlist,.chatWindow,.multiChatDialog{font-family:var(--font)!important}
.friendlist .friendsListSectionTitle{font-family:var(--font-mono,monospace)!important;font-size:10.5px!important;letter-spacing:.14em;text-transform:uppercase;color:var(--mute)!important}
.friendlist .currentUserContainer{border-bottom:1px solid var(--line)!important}
.friendlist .playerName{font-weight:600}
.friendlist .online .playerName,.friendlist .online.playerName{color:var(--st-online,#6fd3ff)!important}
.friendlist .ingame .playerName,.friendlist .ingame.playerName{color:var(--st-ingame,#9be15d)!important}
.friendlist .awayOrSnooze{opacity:.7}.friendlist .offline{opacity:.5}
.friendlist .friendlistListContainer .avatarHolder img,.chatTabSetContainer .avatarHolder img,.ChatSpeaker img{border-radius:var(--avatar-r,50%)!important}
.friendlist .socialTabSearchContainer input{border-radius:999px!important;background:var(--surface-solid-2)!important;border:1px solid var(--line)!important}
.ChatMessageBlock .msg{display:inline-block;max-width:80%;padding:7px 12px!important;margin:2px 0!important;border-radius:var(--bubble-r,14px)!important;background:var(--surface-solid-2)!important;border:1px solid var(--line)}
.ChatSpeaker .speakerName{font-weight:700!important;color:var(--acc)!important}
.ChatSpeaker .speakerTimeStamp{font-family:var(--font-mono,monospace)!important;font-size:10px!important;color:var(--mute)!important}
.chatWindow .chatEntry textarea,.chatWindow .chatEntry .chatTextarea{border-radius:var(--rx)!important;background:var(--surface-solid-2)!important;border:1px solid var(--line)!important;transition:border-color .2s,box-shadow .2s}
.chatWindow .chatEntry textarea:focus{border-color:var(--acc)!important;box-shadow:0 0 0 3px var(--ring)!important}
.chatTabSetContainer .chatTabSelector,.ChatTabs .title-area{border-radius:var(--rx) var(--rx) 0 0!important}
.FriendChatTypingNotification{color:var(--acc)!important}
